INSERT INTO public.questions (
  id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty,
  content_latex, explanation_latex, source_type, source_reference, status, is_active
) VALUES (
  '52141d24-e0a1-4ff9-a1cf-cd9f26e1fb20', '11111111-0000-0000-0000-000000000003', 'c64f775f-ece4-4e6d-ac17-240f89ff14e7', 'b9aed5c1-4912-4806-ae13-28db8414301e',
  'JEE_ADVANCED', 'SINGLE_MCQ', 'ADVANCED',
  'The distance between the parallel lines $3x + 4y + 15 = 0$ and $3x + 4y - 25 = 0$ in Standard Limits is:', 'The distance between parallel lines $Ax + By + C_1 = 0$ and $Ax + By + C_2 = 0$ is $d = \frac{|C_1 - C_2|}{\sqrt{A^2 + B^2}} = \frac{|15 - (-25)|}{\sqrt{3^2 + 4^2}} = \frac{40}{5} = 8$.',
