) VALUES (
  '30dbedfe-08e2-42f8-a3d8-27fbbf668fb4', '11111111-0000-0000-0000-000000000003', 'a81241a6-c421-4cdb-a086-b7c2f3bb2b7b', 'c7f89b6d-f532-4e7f-a15c-f49872cb041a',
  'NEET', 'SINGLE_MCQ', 'EASY',
  'Evaluating the limit in Compound Angle Identities: $\lim_{x \to 0} \frac{\sin(2x)}{\tan(3x)}$ is equal to:', 'Using standard limit properties: $\lim_{x \to 0} \frac{\sin(ax)}{\tan(bx)} = \lim_{x \to 0} \frac{\frac{\sin(ax)}{ax} \cdot ax}{\frac{\tan(bx)}{bx} \cdot bx} = \frac{a}{b} = \frac{2}{3}$.',
  'PREVIOUS_YEAR', 'NEET-2015-MATH-Q21', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
