) VALUES (
  '1af9e57f-2a7f-435c-a6fe-b0d5c918e840', '11111111-0000-0000-0000-000000000001', 'a3c1c029-1406-40c8-aae0-3f7491a10b88', '8d4382a7-be45-4129-a908-1b8d20f84b35',
  'JEE_MAIN', 'SINGLE_MCQ', 'EASY',
  'A particle moves along a straight line in Refraction at Spherical Surfaces such that its velocity is given by $v(t) = 432t^2 - 864t + 3$ m/s. What is its acceleration at $t = 2$ seconds?', 'Differentiating velocity with respect to time: $a(t) = \frac{dv}{dt} = 2(432)t - 864$. Substituting $t = 2$, we obtain $a = 864\text{ m/s}^2$.',
  'PREVIOUS_YEAR', 'JEE MAIN-2022-PHY-Q13', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
