  '5342ce0c-3647-4526-aff5-bb6cb30e18bb', '11111111-0000-0000-0000-000000000003', '4bcf925f-6876-4f0d-ae61-c3c89a456425', 'ccf87fc7-8da1-42de-a127-1318e5d7eaa8',
  'NEET', 'SINGLE_MCQ', 'EASY',
  'Evaluating the limit in Matrix Multiplication & Inverse: $\lim_{x \to 0} \frac{\sin(6x)}{\tan(3x)}$ is equal to:', 'Using standard limit properties: $\lim_{x \to 0} \frac{\sin(ax)}{\tan(bx)} = \lim_{x \to 0} \frac{\frac{\sin(ax)}{ax} \cdot ax}{\frac{\tan(bx)}{bx} \cdot bx} = \frac{a}{b} = \frac{6}{3}$.',
  'PREVIOUS_YEAR', 'NEET-2024-MATH-Q15', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
