INSERT INTO public.questions (
  id, subject_id, chapter_id, topic_id, exam_type, question_type, difficulty,
  content_latex, explanation_latex, source_type, source_reference, status, is_active
) VALUES (
  'f58fb8ac-88c7-4953-a8b6-2ab566d802e9', '11111111-0000-0000-0000-000000000003', '30f11af4-d7b6-4fce-a61e-86df5b4413f2', '59dddf98-9728-48f8-a51e-d0230fb63004',
  'JEE_MAIN', 'SINGLE_MCQ', 'MEDIUM',
  'In Arithmetico-Geometric Series, the value of the definite integral $\int_{0}^{\pi/2} \frac{\sin^3(x)}{\sin^3(x) + \cos^3(x)} dx$ is:', 'Applying King''s property $\int_a^b f(x) dx = \int_a^b f(a+b-x) dx$, let $I = \int_0^{\pi/2} \frac{\sin^n x}{\sin^n x + \cos^n x} dx$. Adding both equations gives $2I = \int_0^{\pi/2} 1 dx = \frac{\pi}{2} \implies I = \frac{\pi}{4}$.',
  'PREVIOUS_YEAR', 'JEE MAIN-2013-MATH-Q4', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
