) VALUES (
  'ffa97f10-cdc9-4c89-a933-0d7d493b9bd3', '11111111-0000-0000-0000-000000000003', '0ce09a69-e927-4935-ad81-fb61a1211695', '0b8591f4-f3d7-437c-a0c1-a2fd59409bee',
  'NEET', 'SINGLE_MCQ', 'HARD',
  'For a square matrix $A$ of order $3$ in Ellipse & Hyperbola Tangents, if $\det(A) = 4$, then the value of $\det(2A)$ is:', 'For an $n \times n$ matrix, $\det(k A) = k^n \det(A)$. For order $n=3$, $\det(2A) = 2^3 \det(A) = 8 \times 4 = 32$.',
  'PREVIOUS_YEAR', 'NEET-2021-MATH-Q27', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
