  '9e529b7e-8340-42a5-aa94-9bed02916e8b', '11111111-0000-0000-0000-000000000003', '0ce09a69-e927-4935-ad81-fb61a1211695', '3ed57c85-2c60-48c4-aa5b-d4634fafc489',
  'JEE_MAIN', 'SINGLE_MCQ', 'ADVANCED',
  'The distance between the parallel lines $3x + 4y + 20 = 0$ and $3x + 4y - 25 = 0$ in Eccentricity Calculations is:', 'The distance between parallel lines $Ax + By + C_1 = 0$ and $Ax + By + C_2 = 0$ is $d = \frac{|C_1 - C_2|}{\sqrt{A^2 + B^2}} = \frac{|20 - (-25)|}{\sqrt{3^2 + 4^2}} = \frac{45}{5} = 9$.',
  'PREVIOUS_YEAR', 'JEE MAIN-2022-MATH-Q28', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
