) VALUES (
  'f26a4ea7-8b72-47e8-ac6d-c2b5e967c362', '11111111-0000-0000-0000-000000000003', 'c64f775f-ece4-4e6d-ac17-240f89ff14e7', '4b82d0ec-ef45-4a88-a19d-6c687c933401',
  'JEE_ADVANCED', 'SINGLE_MCQ', 'EASY',
  'Evaluating the limit in LHospitals Rule: $\lim_{x \to 0} \frac{\sin(6x)}{\tan(3x)}$ is equal to:', 'Using standard limit properties: $\lim_{x \to 0} \frac{\sin(ax)}{\tan(bx)} = \lim_{x \to 0} \frac{\frac{\sin(ax)}{ax} \cdot ax}{\frac{\tan(bx)}{bx} \cdot bx} = \frac{a}{b} = \frac{6}{3}$.',
  'PREVIOUS_YEAR', 'JEE ADVANCED-2014-MATH-Q5', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
