) VALUES (
  '7eab7fca-4186-4396-a887-9df4230127f1', '11111111-0000-0000-0000-000000000003', '691f4024-361c-46dc-a157-a573486e01e6', 'bdfba6de-ff77-4368-a01d-e274ad9baf17',
  'JEE_ADVANCED', 'SINGLE_MCQ', 'EASY',
  'Evaluating the limit in Circular & Constrained Permutations: $\lim_{x \to 0} \frac{\sin(4x)}{\tan(3x)}$ is equal to:', 'Using standard limit properties: $\lim_{x \to 0} \frac{\sin(ax)}{\tan(bx)} = \lim_{x \to 0} \frac{\frac{\sin(ax)}{ax} \cdot ax}{\frac{\tan(bx)}{bx} \cdot bx} = \frac{a}{b} = \frac{4}{3}$.',
  'PREVIOUS_YEAR', 'JEE ADVANCED-2017-MATH-Q23', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
