  '192931f5-c58c-46d2-af9b-db4b822c24c1', '11111111-0000-0000-0000-000000000003', 'a81241a6-c421-4cdb-a086-b7c2f3bb2b7b', 'c7f89b6d-f532-4e7f-a15c-f49872cb041a',
  'NEET', 'SINGLE_MCQ', 'EASY',
  'Evaluating the limit in Compound Angle Identities: $\lim_{x \to 0} \frac{\sin(5x)}{\tan(3x)}$ is equal to:', 'Using standard limit properties: $\lim_{x \to 0} \frac{\sin(ax)}{\tan(bx)} = \lim_{x \to 0} \frac{\frac{\sin(ax)}{ax} \cdot ax}{\frac{\tan(bx)}{bx} \cdot bx} = \frac{a}{b} = \frac{5}{3}$.',
  'PREVIOUS_YEAR', 'NEET-2018-MATH-Q9', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
