  'd9d47d32-36d8-4197-a484-5020d363694c', '11111111-0000-0000-0000-000000000003', 'c802774f-4126-4903-a5dd-95bd24b982d0', 'bf6fba9f-30c5-4d42-a2b5-0b4a4822df4c',
  'JEE_ADVANCED', 'SINGLE_MCQ', 'EASY',
  'Evaluating the limit in Dot and Cross Products: $\lim_{x \to 0} \frac{\sin(4x)}{\tan(3x)}$ is equal to:', 'Using standard limit properties: $\lim_{x \to 0} \frac{\sin(ax)}{\tan(bx)} = \lim_{x \to 0} \frac{\frac{\sin(ax)}{ax} \cdot ax}{\frac{\tan(bx)}{bx} \cdot bx} = \frac{a}{b} = \frac{4}{3}$.',
  'PREVIOUS_YEAR', 'JEE ADVANCED-2017-MATH-Q23', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
