) VALUES (
  'bd805be4-1c40-4ffa-ae78-36db0a337635', '11111111-0000-0000-0000-000000000002', 'fd3629b1-d688-4729-a91b-c6588d1d7e0c', '25a7eb29-c45c-4fcd-a422-c4a32c124861',
  'JEE_ADVANCED', 'SINGLE_MCQ', 'MEDIUM',
  'In the context of Colloids & Tyndall Effect, which of the following compounds exhibits maximum paramagnetic behavior?', '$[\text{Fe}(\text{H}_2\text{O})_6]^{2+}$ contains $\text{Fe}^{2+}$ ($d^6$) with a weak field ligand $\text{H}_2\text{O}$, resulting in 4 unpaired electrons ($t_{2g}^4 e_g^2$) and maximum magnetic moment $\mu = \sqrt{4(4+2)} = 4.90\ \text{BM}$.',
  'PREVIOUS_YEAR', 'JEE ADVANCED-2020-CHEM-Q26', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
