) VALUES (
  '9a3e8367-1274-431c-a95f-179ba0317067', '11111111-0000-0000-0000-000000000001', '7e8026da-d616-467d-a8d1-2344f2d8e460', '827d0d2e-384e-4dde-a6be-f76113c29e11',
  'JEE_ADVANCED', 'SINGLE_MCQ', 'MEDIUM',
  'In an experiment on Gauss Law Applications, a block of mass $m = 4\text{ kg}$ is resting on a rough horizontal surface with coefficient of static friction $\mu_s = 0.3$. The minimum horizontal force required to start moving the block is (take $g = 10\text{ m/s}^2$):', 'The limiting static friction is $f_{s,\max} = \mu_s N = \mu_s m g$. Substituting values gives $F_{\min} = 0.3 \times 4 \times 10 = 12.0\text{ N}$.',
  'PREVIOUS_YEAR', 'JEE ADVANCED-2017-PHY-Q8', 'APPROVED', TRUE
) ON CONFLICT (id) DO NOTHING;
